const fs = require('node:fs');
const path = require('node:path');
const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
const code = value => `<pre><code>${escape(value)}</code></pre>`;
const table = (heads, rows) => `<div class="table-scroll"><table><thead><tr>${heads.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note = text => `<aside class="note">${text}</aside>`;
const pages = [
  ['index', 'Overview', 'Local capabilities. Explicit access.', `
    <p class="lede">Agent Uplink connects authorized cloud applications to services on enrolled computers. The computer opens outbound connections; it does not need an inbound public port.</p>
    ${note('Development preview. This is a development-build and operator-managed project, not a generally available hosted service. The website is documentation, not a running relay.')}
    <h2>Choose your capability</h2>
    ${table(['Capability','Purpose','Current boundary'],[
      ['<a href="/docs/mcp">MCP</a>','Call local tools through Model Context Protocol.','HTTP and stdio export bridges exist; compatibility is profile-specific.'],
      ['<a href="/docs/acp">ACP</a>','Interact with a fixed local CLI agent through Agent Client Protocol.','HTTP/SSE bridge with local interoperability evidence; acceptance work remains.'],
      ['<a href="/docs/cua">Computer use</a>','Expose explicitly allowed screen and input operations.','Adapter and synthetic fixtures exist; real desktop verification is outstanding.'],
      ['<a href="/docs/filesystems">Filesystems</a>','Access confined mounts through a shared TypeScript client.','9P-over-WebSocket client and four SDK adapters; not universal SDK or platform certification.']])}
    <h2>Start with the transport</h2><p>Install the CLI binaries, validate configuration, provision device identity and consumer authorization, then run a controlled echo connection before enabling service exports. Follow <a href="/docs/setup">Setup</a> for the prerequisites and commands.</p>
    <h2>What Agent Uplink is not</h2><p>It is not a model runtime, conversation store, agent scheduler, generic shell endpoint or unrestricted TCP proxy. Your application retains its orchestration and your computer retains local service policy.</p>
    <h2>Reading support claims</h2><p><strong>Implemented</strong> means code exists. <strong>Locally verified</strong> means the named scope has repository evidence. Neither means every operating system, backend, failure mode or production deployment is certified. The <a href="/docs/support">support matrix</a> records the limits.</p>`, ['README.md','docs/architecture.md','docs/tasks.md']],
  ['downloads', 'Downloads', 'Install the latest development build.', `
    <p class="lede">Successful main CI builds produce versioned GitHub prereleases. These are development snapshots, not production-certified releases.</p>
    <div class="note" data-release-info aria-live="polite"><p>Checking published versions...</p><a href="https://github.com/andymac4182/agentuplink/releases">View GitHub releases</a></div>
    <h2>Choose and verify an archive</h2><p>Download the archive for your operating system and CPU together with its adjacent SHA-256 file. The release tag includes the workspace version, main CI run ID and source commit. The archive's release.json records the same identity.</p>
    ${code('# Linux, from the download directory:\nsha256sum -c agentuplink-*.tar.gz.sha256\n\n# macOS, from the download directory:\nshasum -a 256 -c agentuplink-*.tar.gz.sha256')}
    <p>Run against only the chosen archive/checksum pair. Windows users can compare <code>Get-FileHash .\\ARCHIVE.zip -Algorithm SHA256</code> with the downloaded .sha256 file. Stop if the values differ.</p>
    <h2>Linux and macOS</h2><p>Extract the chosen archive into an empty directory, then run these commands from that directory:</p>${code('mkdir -p "$HOME/.local/bin"\ninstall -m 755 bin/tunnel-client bin/tunnel-relay bin/tunnel-deadman "$HOME/.local/bin/"\nexport PATH="$HOME/.local/bin:$PATH"\ntunnel-client --help\ntunnel-relay --help')}
    <p>Add that PATH entry to your shell profile for later terminals. Keep the three binaries from the same release together: the client and supervised services need the adjacent tunnel-deadman helper.</p>
    <h2>Windows</h2><p>Extract the ZIP to a permanent location, keep both .exe files (tunnel-client and tunnel-deadman) in its bin directory, and add that directory to your user PATH. Open a new terminal and run <code>tunnel-client --help</code>. Filesystem exports are unsupported on Windows: client configuration validation and connect refuse an fs export. A Windows binary also does not imply Unix process-group supervision or complete adapter support. The relay is not built for Windows: it runs on Linux and macOS.</p>
    <h2>Platform boundaries</h2><p>Linux x64 builds use Ubuntu 24.04 and require compatible glibc libraries. macOS and Windows binaries are unsigned; macOS packages are not notarized. Do not disable operating-system protections globally to run a build. Review source, checksum and publisher trust before granting a local exception.</p>
    <p>The repository also contains a single-target release-bundle verifier covering checksums, provenance, embedded licence texts, runtime assets, CLI/config probes and system-library portability. Its recorded local evidence is not a published GitHub release or certification of every download target. Packaged end-to-end operations and rotation remain separate acceptance requirements.</p>
    <h2>Configure before connecting</h2><p>Archives include example configuration templates, not credentials or a running relay. Read repository operator documentation at the source commit in the CI archive's <code>release.json</code>; separately built maintainer bundles use <code>PROVENANCE.txt</code>. This website describes reviewed main, which may be newer than your binary. Continue with <a href="/docs/setup">setup</a>. Latest-version lookup uses the public GitHub releases API; if releases are private, view them while authenticated on GitHub instead.</p>
    <h2>Building from source</h2><p>If no release is published, use an authorized source checkout and the pinned toolchain. This is the developer fallback, not the installed CLI workflow. On Linux or macOS:</p>${code('cargo build --release --locked -p tunnel-client -p tunnel-relay -p tunnel-deadman --bins')}
    <p>On Windows, build only the device binaries:</p>${code('cargo build --release --locked -p tunnel-client -p tunnel-deadman --bins')}
    <p>Current main does not ship a Windows relay. A manually built Windows relay exits 2 before running any command; host the relay separately on Linux or macOS.</p>
    <p>Keep the resulting binaries together in target/release. Native dependency and runtime acceptance remains separate from compilation.</p>`, ['.github/workflows/release.yml','scripts/package_release.py','scripts/publish_release.py']],
  ['setup', 'Setup', 'Install and connect an enrolled computer.', `
    <p class="lede">An operator-managed setup using installed Agent Uplink CLI binaries and a provisioned relay environment.</p>
    ${note('There is no one-command production installer or public relay supplied by this website. Do not use synthetic harness credentials, identities or grants in a real deployment.')}
    <p>Current main includes first-time catalog provisioning for one tenant, user, device credential, service and grant in a fresh namespace. A single-relay synthetic echo path has scoped local evidence; you still supply TLS Redis, listener certificates and identity/certificate issuers. Cluster membership publishing and the HTTPS checkpoint authority remain unshipped. Older binaries may not have the provisioning commands.</p>
    <h2>1. Prepare the environment</h2><ul><li>Matching platform bundles from the <a href="/docs/downloads">downloads page</a>. Keep each bundle's binaries together on PATH; device and relay hosts must use the same version.</li><li>A Linux or macOS relay host with separate consumer HTTPS and device mTLS listeners.</li><li>An authoritative Redis catalog with persistence, TLS and a recovery policy.</li><li>An external identity issuer, configured JWT verification keys, tenant/user/device records and explicit service grants.</li><li>Device certificates and trusted CA material supplied through your operator's provisioning process.</li></ul>
    <p>Use Linux or macOS for the relay host. Windows is device-only: install its matching <code>tunnel-client.exe</code> and <code>tunnel-deadman.exe</code> together. Run the relay configuration, provisioning and recovery commands below on the separate Unix relay host, not the Windows device.</p>
    <h2>2. Check the installed CLI</h2><div class="note" data-release-info aria-live="polite"><p>Checking published versions...</p><a href="https://github.com/andymac4182/agentuplink/releases">View GitHub releases</a></div><p>On the device:</p>${code('tunnel-client --help')}<p>On the Linux or macOS relay host:</p>${code('tunnel-relay --help')}
    <p>The product name changed; the <code>tunnel-client</code> and <code>tunnel-relay</code> binary names remain unchanged.</p>
    <h2>3. Configure the relay</h2><p>Use <code>examples/m1-relay.toml</code> as a schema reference, not a ready deployment. Replace its placeholder values and certificate paths. Keep private material outside source control.</p>
    ${table(['Configuration','Required operator decision'],[
      ['consumer_bind / device_bind','Separate listener addresses; the device listener requires client certificates.'],
      ['oidc_issuer / oidc_audience / oidc_jwks_path','Your consumer identity issuer, accepted audience and verification key file.'],
      ['redis_url / redis_namespace','TLS Redis endpoint and a durable namespace. The namespace accepts 1–96 ASCII letters, digits, periods, underscores or hyphens.'],
      ['TLS certificate, key and CA paths','Correct listener identities and the device certificate trust boundary.'],
      ['node_id / boot_id / deployment_incarnation','Keep the coordinated relay identity and deployment incarnation. For a single relay, omit the example boot_id line so each process generates a fresh boot identity. Do not change the deployment incarnation to bypass a recovery error.']])}
    <p><code>oidc_jwks_path</code> is a local JSON key set, not a JWKS URL. The relay accepts RSA keys with a non-empty <code>kid</code>, <code>n</code> and <code>e</code>, and <code>alg</code> set to RS256 or omitted. Key rotation requires updating that file and restarting the relay. Tokens need RS256, a known key ID, an exactly matching issuer (including trailing slash), an accepted audience, a non-empty subject and valid expiry/not-before times with no clock leeway. Scope is a space-separated string. No issuer or token-generation tool is shipped.</p>
    ${code('tunnel-relay \\\n  check-serve-config --config /absolute/path/relay.toml')}
    <p>This dry run checks the serving configuration document. It does not read referenced credentials, connect to Redis, verify the deployment or provision authority records. The legacy <code>check-config</code> validates a different configuration type.</p>
    <h2>4. Configure the device</h2><p>Start from <code>examples/m1-client.toml</code>. Resolve certificate paths relative to the client configuration file. Replace the device ID, relay URL and all credential references.</p>
    ${code('device_id = "your-enrolled-device"\nrelay_url = "wss://relay.example.test/v1/tunnel/control"\n\n[credentials]\nclient_certificate = "credentials/device-cert-chain.pem"\nclient_key = "credentials/device-key.pem"\nserver_ca = "credentials/relay-ca.pem"')}
    <p>This excerpt is not a complete configuration. Keep the example's required limits and rotation sections. Its synthetic echo export is for a controlled transport smoke test, not filesystem, MCP, ACP or desktop access.</p>
    <h2>5. Provision and validate credentials</h2>${code('tunnel-client \\\n  config check --config /absolute/path/client.toml\n\ntunnel-client \\\n  credentials create --config /absolute/path/client.toml \\\n  --csr-out /absolute/path/device.csr')}
    <p>Have your operator sign the CSR with the approved device issuer and establish the matching catalog identity and grants. Creating a CSR does not enroll or authorize a device.</p>
    ${code('tunnel-client \\\n  credentials import --config /absolute/path/client.toml \\\n  --certificate /absolute/path/device-cert-chain.pem \\\n  --server-ca /absolute/path/relay-ca.pem\n\ntunnel-client \\\n  doctor --config /absolute/path/client.toml --json')}
    <p><code>doctor</code> performs local checks. A network doctor, enrollment-code workflow and managed credential renewal are not delivered commands in this reviewed CLI.</p>
    <p>Current main requires an X.509 v3 device certificate with a device-role URI SAN matching the profile's device UUID. <code>credentials import</code> reports a missing or wrong SAN separately from a pending-key mismatch and refuses the invalid certificate before installation.</p>
    <p>Current main keeps <code>result</code> present even on configuration or credential failure, including host capability details. Each check reports its own status: <code>not_run</code> is distinct from <code>failed</code>. Older builds may return <code>result: null</code>; that is not evidence that capabilities passed. Correct the reported error and rerun.</p>
    <p>On Unix, <code>PROCESS_CONTAINMENT_SENTINEL_MISSING</code> means the helper was not found; <code>PROCESS_CONTAINMENT_SENTINEL_UNUSABLE</code> means the candidate is not a regular file or the process lacks execute permission. Keep the genuine packaged <code>tunnel-deadman</code> beside the client and replace an invalid candidate with the matching helper. Both conditions report degraded containment without changing the doctor's verdict or exit code.</p>
    <p><code>PROCESS_CONTAINMENT_SENTINEL_PRESENT</code> establishes a regular file and kernel-granted execute permission, not helper identity or guaranteed startup. Doctor does not run the candidate. A later startup failure produces a separate warning; non-Unix process containment remains unsupported.</p>
    <h2>6. Provision a fresh catalog</h2><p>Prepare a records document using <code>examples/m6-catalog.toml</code> from the matching source revision. Its certificate path is relative to that document. The client device ID must be the catalog device UUID; its certificate needs URI SAN <code>urn:agent-tunnel:device:&lt;device UUID&gt;</code>, and its export table must use the catalog service UUID. Replace synthetic placeholders consistently.</p>
    <p>Choose one initial service before provisioning. Current main accepts <code>echo</code>, <code>http-forward</code> for MCP or ACP, and <code>fs</code>; other types, including computer use, are not supported by this command. Initial provisioning creates one service; use the catalog-change commands below for later additions, not another <code>provision-catalog</code> run.</p>
    ${table(['Service','Records template','Required fields and grants'],[['MCP','examples/m6-catalog-mcp.toml','http_forward_profile = mcp-2025-11-25 or mcp-2026-07-28; http:invoke.'],['ACP','examples/m6-catalog-acp.toml','http_forward_profile = acp-http-v1; http:invoke.'],['Filesystem','examples/m6-catalog-fs.toml','fs_case_sensitivity = sensitive or insensitive-preserving; fs:connect plus at least one of fs:read, fs:list, fs:write or fs:delete.']])}
    <p>For HTTP services, the relay configuration must enable the same profile in <code>[http_forward] profiles</code>; use that configuration for both provisioning and serving. The dry run refuses a missing or unsupported profile and invalid filesystem metadata or grants. The device export must match the service UUID and protocol, with its own backend or confined root. Example comments show the client export shape. Older provisioning builds omitted this metadata and could leave these services returning 404.</p>
    ${code('tunnel-relay provision-catalog --config /absolute/path/relay.toml --records /absolute/path/catalog.toml --dry-run\n\n# The following commands write to the configured Redis namespace:\ntunnel-relay activate-first-incarnation --config /absolute/path/relay.toml\ntunnel-relay provision-catalog --config /absolute/path/relay.toml --records /absolute/path/catalog.toml')}
    <p>The dry run reads configuration, records and the certificate but contacts no Redis and writes nothing. Activation requires an empty namespace. Provisioning must follow activation and succeed before <code>serve</code> starts; otherwise relay-created keys can prevent provisioning. Provisioning is once per namespace, not an update or repair command. Catalog-change commands can add records later, but do not repair a partially provisioned namespace. Do not delete authority keys or bypass recovery.</p>
    <h2>7. Start the provisioned relay and device</h2>${code('tunnel-relay \\\n  serve --config /absolute/path/relay.toml\n\n# On the enrolled computer, in a separate terminal:\ntunnel-client \\\n  connect --config /absolute/path/client.toml --json')}
    <p>Service and grant operations use exact names such as <code>echo:invoke</code>. Provisioning and its dry run reject names containing <code>*</code>; wildcard grants are not supported.</p>
    <p>The client runs in the foreground. Start only after catalog records, grants, identity and trust have been provisioned. Relay connectivity alone does not grant access to an export. Add capability-specific configuration only after checking its support boundaries.</p>
    <h2>After initial provisioning</h2><p>Current main supplies seven <code>tunnel-relay</code> catalog-change commands for the same namespace while <code>serve</code> runs. Each takes the relay's <code>--config</code> and supports <code>--dry-run</code>. Older binaries may not include them.</p>
    ${table(['Command','Input and effect'],[['add-user','--records USER.toml: [user] with tenant, id, display_name and oidc_subject; joins an existing tenant.'],['add-device','--records DEVICE.toml: [device] with tenant, owner, id, display_name and certificate; owner must be an existing member.'],['add-service','--records SERVICE.toml: [service] with tenant, device, id, type, display_name, operations and the required protocol metadata.'],['set-grant','--records GRANT.toml: [grant] with tenant, user, device, service and operations; adds or replaces the grant and advances its revision.'],['revoke-grant','--tenant UUID --user UUID --device UUID --service UUID: removes one grant.'],['revoke-device','--tenant UUID --device UUID: revokes the device, its credentials and grants, and its owner lease.'],['revoke-credential','--tenant UUID --device UUID --credential UUID: revokes one device credential.']])}
    ${code('tunnel-relay add-user --config /absolute/path/relay.toml --records /absolute/path/user.toml --dry-run\ntunnel-relay add-device --config /absolute/path/relay.toml --records /absolute/path/device.toml --dry-run\ntunnel-relay add-service --config /absolute/path/relay.toml --records /absolute/path/service.toml --dry-run\ntunnel-relay set-grant --config /absolute/path/relay.toml --records /absolute/path/grant.toml --dry-run')}
    <p>Prepare separate records documents using <code>docs/operator.md</code> section 2.5 from the matching source revision. Do not pass an entire initial-provisioning document to these commands. Certificate paths are relative to the records document. Dry runs validate record shape, certificate identity and service rules without contacting Redis; they cannot confirm existing tenants, membership, duplicates or grant compatibility with stored services. Remove <code>--dry-run</code> only when ready to write, in dependency order: user, device, service, grant.</p>
    <p>Each catalog change uses a single Redis script and checks the active incarnation. Additions reject duplicate identities rather than overwriting them; <code>set-grant</code> deliberately replaces an existing grant and refuses a revoked device. Keep the credential ID printed by <code>add-device</code>: no command lists credentials. Device export names and local policies must still match the service records; a catalog change does not reload the client's configuration.</p>
    <p>New records and grants affect the next connection or request without a relay restart. Grant revocation refuses subsequent requests, but already admitted work can retain its authorization for up to five seconds. Device and credential revocation also close live sessions during maintenance. Scope and timing limits are on the <a href="/docs/support">support page</a>. If a command is interrupted with an unknown outcome, reconcile state before retrying; atomic execution does not guarantee the caller received its result.</p>
    <p><strong>Still unsupported:</strong> adding a second tenant; changing or deactivating users or memberships; changing service types or operations; reactivating revoked devices or credentials; and renewing a certificate for the same device. A replacement can use a new device UUID, key and certificate, followed by its service and grant, then revocation of the old device. That keeps the namespace but changes device/export identities; it is not in-place renewal.</p>
    <h2>Reconnect and service management</h2><p>Current main's foreground <code>connect</code> retries reconnectable failures by default, with exponential delay ceilings from 1 to 60 seconds and jitter between half and all of each ceiling. Each reconnect starts a fresh session, not a replay of interrupted operations. Invalid configuration and classified credential refusals are terminal; opaque protocol-version or cluster identity refusals may still be retried. Older builds exit on connection loss.</p>
    ${code('# Optional client profile settings (defaults shown):\n[reconnect]\nenabled = true\ninitial_delay_ms = 1000\nmax_delay_ms = 60000\nmax_attempts = 0\n\n# Let an external supervisor own all restarts instead:\n# tunnel-client connect --config /absolute/path/client.toml --no-reconnect')}
    <p><code>max_attempts = 0</code> means no attempt limit. A finite value bounds consecutive retries; the count resets only after a session stays ready for the maximum delay. JSON lifecycle events report <code>disconnected</code>, <code>backoff</code>, <code>reconnecting</code> and <code>reconnected</code>. Stop and restart to load changed configuration. See <a href="/docs/support">support</a> for the stale-owner network-change limitation.</p>
    <p>The source tree's <code>examples/service/</code> contains systemd client/relay units and a macOS launchd client example; these are not included in release bundles. Adjust paths, service accounts and stop timeouts. Repository evidence covers static checks for all examples and a limited live systemd client test; the relay unit was not live-tested and the launchd example was linted, not loaded. Windows service installation remains unsupported.</p>
    <p>Upgrade by stopping, replacing the binaries from one matching platform bundle (three on Linux/macOS; client and deadman only on Windows), and starting with the same configuration. Keep device and relay versions matched across hosts. Preserve credentials, Redis catalog and relay state files. Sessions and supervised children restart; interrupted mutations can have unknown outcomes. Mixed-version deployments, downgrades and seamless rolling upgrades are not supported.</p>
    <h2>Process lifecycle</h2><p>Current main handles SIGINT and SIGTERM on Unix during <code>connect</code> and <code>serve</code>. An orderly live-session or serving stop exits 0; interruption before readiness/startup completes or during reconnect backoff exits 130. A second stop request abandons the shutdown wait with exit 130. Client drain timeout also exits 130; its bound is the configured handshake timeout plus overlap. Relay serving drain has no overall deadline, so a service manager needs a stop timeout and escalation policy. Windows handles Ctrl-C only; SIGHUP is not handled. Older builds may lack this behavior.</p><p>For relay commands that write state, including activation, provisioning and recovery, the first stop request lets the command finish and report its outcome. A second request abandons it with exit 130 and an unknown outcome. Do not retry a potentially partial catalog write or reuse a consumed recovery approval blindly. Scoped local process tests and unit tests exist, but not every shutdown phase or platform is verified.</p>
    <h2>Single-relay Fly.io deployment</h2><p>The source tree now includes <code>deploy/fly/</code> Dockerfiles, entrypoints and configuration templates, plus the ordered runbook in <code>docs/deploy-fly.md</code>. This is an operator-managed alpha deployment, not a public relay service or a one-command installer. Use the guide and templates from the same reviewed source revision as your image.</p>
    <p>The topology is one relay and one private, persistent TLS Redis instance in the same region. Both consumer HTTPS and device mTLS use TCP passthrough so the relay terminates TLS itself. Supply your own listener certificates, device trust and identity issuer; do not put credentials in images or source control. This configuration is not a cluster: do not scale either app above one machine or use a deployment strategy that overlaps two unclustered relays on the namespace.</p>
    <p>Follow the runbook's order: build and push the image without starting the serving relay, validate configuration, activate the empty namespace, provision the catalog, then deploy that exact image. Starting <code>serve</code> between activation and provisioning can leave the namespace unprovisionable. Use a build at or after <code>721ed2a</code> for the corrected Redis startup connection budget. Provisioning still uses the installed <code>tunnel-relay</code> commands described above.</p>
    <p>Plan downtime: relay replacement ends sessions. Current Fly templates enable the single-relay Redis continuity option, but an in-place restart must satisfy the durability and continuity checks described on the <a href="/docs/support">support page</a>. A restore, replacement volume or failover is not covered. Non-cluster <code>/readyz</code> still does not prove Redis health. Machines, storage, addresses, traffic and remote builds may incur charges; check current provider pricing before creating resources.</p>
    <p><strong>Hosted upgrade evidence:</strong> the repository records an in-place upgrade of an already provisioned single relay to <code>main-af23c2f</code> on 2026-09-24, with Redis continuity enabled at 5 seconds. A matching Mac client completed 150 echoes in one session. After a SIGTERM relay restart, it reconnected automatically; the second echo attempt succeeded four seconds after the restart. These are recorded observations, not timing guarantees or a new test run here.</p>
    <p><strong>Evidence boundary:</strong> Redis persistence settings were checked on Fly, but a Fly Redis restart was not exercised. Local rehearsal covered Redis restart/crash and rollback; it does not establish hosted recovery or supported mixed-version operation. Fresh hosted activation and provisioning with a main-built image remain unverified; earlier hosted provisioning used a diagnostic image. Rolling back to <code>main-721ed2a</code> also removes Redis continuity support. Full adapter and production acceptance remain separate.</p>
    <p><strong>Catalog commands on Fly:</strong> the relay image entrypoint accepts serving, configuration checking, initial activation/provisioning and Redis re-binding, but not the catalog-change commands such as <code>add-device</code> or <code>set-grant</code>. Do not pass those through the image's normal <code>fly machine run</code> entrypoint. Direct relay CLI execution through <code>fly ssh console</code> is the runbook's proposed path, not a verified hosted workflow.</p>
    <h2>Acceptance before deployment</h2><p>A downloaded build is not a replacement for deployment-specific Redis/socket and capability acceptance. Cluster support and applicable adapter gates remain private-alpha requirements. Use dedicated disposable desktop VMs for computer-use tests. Developer build instructions are separate on the <a href="/docs/downloads">downloads page</a>.</p>`, ['examples/m1-client.toml','examples/m1-relay.toml','crates/tunnel-client/src/main.rs','docs/operator.md','docs/runtime.md','docs/deploy-fly.md','deploy/fly/','docs/tasks.md']],
  ['architecture', 'Architecture', 'An outbound connection with scoped authority.', `
    <p class="lede">The relay connects a consumer to a specific enrolled device and service. Authorization and local export policy both constrain what can happen.</p>
    ${code('Authorized consumer\n        | HTTPS or filesystem WebSocket\n        v\nRelay ingress -- private mTLS HTTP/3 --> owning relay\n        |                                  |\n        +----- Redis authority catalog ----+\n                                           ^\n                          outbound mTLS WebSockets\n                                           |\n                              Enrolled device client\n                              /     |      |      \\\n                            MCP    files   ACP    CUA')}
    <h2>Three transport roles</h2>${table(['Role','Boundary'],[['Consumer','HTTPS APIs and consumer WebSockets authenticate an application acting for a user.'],['Device','The enrolled client initiates mutual-TLS control and data WebSockets. Both sockets require device identity.'],['Relay peer','Private HTTP/3 uses separate relay identities and approved public-key membership, not device credentials.']])}
    <h2>Permissions are not implied by connectivity</h2><p>Authority is scoped by tenant, principal, device, service and permitted operations. Local configuration defines exports. A connected computer is not an unrestricted remote desktop or shell.</p>
    <h2>Two sockets in steady state</h2><p>Each device uses one control and one data socket. Ordered data-socket rotation permits a bounded temporary third socket while old streams drain. Transport acknowledgements do not prove an application side effect completed.</p>
    <h2>Finite echo retention</h2><p>Current main implements owner-issued <code>STREAM_FORGET</code> for successfully completed finite echoes and explicitly rejected opens, reclaiming connector retention only after the required terminal and acknowledgement evidence. Cleanup waits while rotation or recovery holds the stream roster. Rotation fencing now includes the dispatched FIN and preserves completed echoes until the attempt finishes.</p><p>These are scoped fixes, not complete echo or transport acceptance. Repository regression gates cover more than 128 sequential echoes and echoes crossing rotations; they were not rerun for this website review. Cancellation, RESET, authorization invalidation and timeout cleanup remain open, as does automatic session replacement when retained opens exhaust capacity. See <a href="/docs/support">support boundaries</a>.</p>
    <h2>State and recovery</h2><p>Redis is the authoritative catalog and coordination store. Process-local sockets and in-flight work are ephemeral. The supported coordination profile uses one authoritative Redis primary; replication is not a promise of automatic, lossless failover. Recovery must reconcile revocations and fence old ownership.</p>
    <p>A Redis restart changes its run identity. Current main has a narrow, single-relay path to keep the namespace after an in-place restart from the same durable AOF: a serving relay can verify its continuity token, or an operator can attest the restart using <code>rebind-redis-run</code>. See <a href="/docs/support">the prerequisites and exclusions</a>. Neither path is backup-restore or failover recovery. Cluster Redis restarts, restores and ambiguous authority still need externally approved recovery; its signing authority is not shipped. A fresh namespace is a new deployment, not restoration of old authorization. Never delete authority keys to bypass fencing.</p>
    <h2>Cluster readiness</h2><p>In current main, <code>/readyz</code> and public admission both require a non-empty verified transport key-pin set, alongside membership and peer readiness. If those pins are withdrawn, readiness fails and public work is refused even before the next peer refresh. Restoring pins alone is not enough if another readiness condition still fails.</p><p>This check applies to the cluster peer runtime, not the non-cluster M1/M2 profile. Readiness is an admission check, not proof of an end-to-end service operation or full cluster acceptance. Source and regression tests cover pin withdrawal and recovery; deployment-specific verification remains required.</p>
    <h2>Trust boundary</h2>${note('The relay terminates encrypted connections and is trusted with service traffic. Agent Uplink does not claim end-to-end encryption through an untrusted relay.')}<p>Private keys stay outside the catalog. Diagnostics should expose identifiers, phases and counters, not payloads or credentials. Never automatically replay an ambiguous click, write or agent prompt after losing its outcome.</p>`, ['docs/architecture.md','docs/protocol.md','docs/cluster.md']],
  ['mcp', 'MCP', 'Make local tools reachable by authorized agents.', `
    <p class="lede">Model Context Protocol exposes tools and related protocol exchanges. Agent Uplink transports selected MCP profiles to fixed local HTTP services or supervised stdio servers.</p>
    <h2>Compatibility profiles</h2>${table(['Profile','Lifecycle','HTTP surface','Stdio ownership'],[['mcp-2026-07-28','Discovery and per-request metadata; no lifecycle translation.','POST; GET and DELETE answered 405 before backend dispatch.','One child per request; no cross-request child state.'],['mcp-2025-11-25','Initialize lifecycle and session ownership.','POST, GET and DELETE.','One child per session.']])}
    <p>These are the repository's pinned profiles, not a claim to support every MCP revision. The bridge forwards raw JSON-RPC bytes rather than retyping messages and dropping unknown metadata.</p>
    <h2>Local export choices</h2><ul><li><strong>HTTP:</strong> a locally configured backend destination, not a caller-supplied URL.</li><li><strong>Stdio:</strong> a fixed local executable and launch policy, supervised by the device.</li><li><strong>Consumer:</strong> an authorized application calls the enrolled device/service route; a tool name is not an authorization grant.</li></ul>
    <h2>Provision and call</h2><p>Use <code>examples/m6-catalog-mcp.toml</code> with the <a href="/docs/setup">fresh-catalog workflow</a>. Set the catalog and device export to the same pinned MCP profile and enable it in the relay's <code>[http_forward] profiles</code>. The consumer route is <code>/v1/devices/{device_id}/services/{service_id}/http/mcp</code>, with token scope and grant <code>http:invoke</code>.</p><p>Current profiles refuse <code>User-Agent</code> and <code>Accept-Encoding</code> request headers with 400 <code>HTTP_INVALID_HEAD</code>. Many HTTP clients send these automatically; omit them rather than assuming SDK defaults are compatible. Provisioning regression gates use synthetic backends and do not establish compatibility with every MCP server.</p>
    <h2>Limits and interoperability</h2>${table(['Area','Current scope'],[['Pinned interoperability','The official rmcp 3.4.0 fixture exercises the two profiles; this is not certification of every SDK or server.'],['Request size','Default 1 MiB, configured ceiling 16 MiB.'],['JSON response','Default 8 MiB, ceiling 64 MiB; enforced on the device.'],['Cumulative SSE response','Default 64 MiB, ceiling 1 GiB.'],['Consumer transport','HTTP/1.1 and HTTP/2 accepted by the profile; full cross-client coverage remains separate.']])}
    <h2>Do not assume</h2><p>Browser access, unrestricted headers, OAuth flows, Last-Event-ID replay, every resources/prompts/sampling/elicitation exchange, and cross-platform child cleanup are not blanket supported. Header allowlists differ by profile. In particular, the browser Origin/CORS profile is not delivered.</p>
    <h2>Failure behavior</h2><p>A transport interruption is not proof that a tool did not run. Respect explicit unknown outcomes and cancellation semantics. Do not blindly retry a side-effecting tool call. Session isolation and wider conformance acceptance still have open work.</p>`, ['docs/mcp.md','docs/tasks.md','crates/tunnel-mcp']],
  ['acp', 'ACP', 'A remote conversation with a local CLI agent.', `
    <p class="lede">Agent Client Protocol connects a host application to an agent. Agent Uplink carries those conversations to an allowlisted agent supervised by the enrolled device.</p>
    <h2>Connection flow</h2>${code('initialize -> connection ID\nopen connection event stream\nsession/new -> session ID\nopen session event stream\nsession/prompt -> updates and eventual result\npermission request -> host decision -> agent response\nDELETE connection -> cleanup')}
    <h2>HTTP binding</h2><p>The device/service endpoint has the form:</p>${code('/v1/devices/{device_id}/services/{service_id}/http/acp')}
    <p>Provision with <code>examples/m6-catalog-acp.toml</code> through the <a href="/docs/setup">fresh-catalog workflow</a>: type <code>http-forward</code>, profile <code>acp-http-v1</code>, and grant/token scope <code>http:invoke</code>. Enable that profile in the relay and configure the matching device export. The consumer must use HTTP/2; HTTP/1.1 receives 501 <code>HTTP_UNSUPPORTED_FEATURE</code>. Omit <code>User-Agent</code> and <code>Accept-Encoding</code>, which this profile refuses.</p>
    ${table(['Exchange','Behavior'],[['POST initialize','200 JSON and Acp-Connection-Id.'],['GET with connection ID','Connection-scoped SSE messages.'],['GET with connection and session IDs','Session-scoped SSE messages.'],['Subsequent POST','202 admission response; the JSON-RPC result arrives on the event stream.'],['DELETE with connection ID','Termination request and cleanup.']])}
    ${note('HTTP 202 means accepted, not completed. Read the corresponding protocol result and preserve unknown outcomes if the connection is lost.')}
    <h2>What has evidence</h2><p>The pinned official Rust client has driven initialize, sessions, prompt updates, permission callbacks and DELETE against the bridge. Local cluster evidence covers a declared subset of rotation, ownership, revocation and tenant-isolation behavior. The full ACP milestone is not complete.</p>
    <h2>Important limits</h2><ul><li>The public profile follows the selected ACP HTTP draft. It is not a generic WebSocket agent gateway.</li><li>Batch requests are refused by the selected profile even though the pinned upstream SDK has batch support.</li><li>Browser CORS/Origin access is a separate acceptance gate.</li><li>Peer-key rotation and simultaneous saturation of both forwarding segments remain outside completed acceptance.</li><li>The caller cannot supply an arbitrary executable or shell command.</li><li>Lost prompts are not automatically replayed, and child restarts must not silently repeat work.</li></ul>
    <h2>Permissions and workspace</h2><p>Connection/session ownership includes principal, tenant, device, service and policy revision. Permission callbacks go to the host and do not widen local grants. An agent-visible working directory is scoped to its configured export, not an invitation to disclose arbitrary host paths.</p>`, ['docs/acp.md','docs/tasks.md','crates/tunnel-acp-export']],
  ['cua', 'Computer Use', 'Desktop operations behind an explicit policy.', `
    <p class="lede">The computer.v1 adapter targets a locally supervised CUA Computer Server. It is not an unrestricted proxy to the server's entire API.</p>
    ${note('No real desktop OS/backend is currently advertised as verified. The adapter has code and synthetic test evidence, but dedicated disposable-VM acceptance remains open. Do not test it against an active personal desktop.')}
    <h2>Pinned backend</h2><p>The reviewed backend is <code>cua-computer-server 0.3.46</code>, a Python sidecar. The profile pins its <code>/cmd</code> command surface. CUA Driver is an optional backend of that server, not a separately supported Rust or stdio service.</p>
    <h2>Capability mapping</h2>${table(['Capability','Backend command family','Boundary'],[['Screen capture','screenshot','Bounded image data and dimensions; no live-video guarantee.'],['Screen and cursor state','get_screen_size, get_cursor_position','Backend-specific capabilities must be discovered.'],['Pointer input','left_click, right_click, double_click, move_cursor, drag, scroll','Explicit permission and exclusive input-controller policy.'],['Keyboard input','type_text, press_key, hotkey','Layout and backend parameter semantics require real-backend verification.'],['Accessibility','get_accessibility_tree','Only when the backend actually supplies supported data.']])}
    <h2>Parameter compatibility</h2><p>Command and parameter names are now pinned against the released backend source. Drag is sent as a two-point <code>path</code>; scroll uses <code>x</code> and <code>y</code> as wheel amounts, not cursor coordinates. These are source-backed compatibility corrections, not a real-backend test result.</p>
    <h2>Known backend limitations</h2><ul><li><strong>Display selection:</strong> the pinned backend does not accept the requested display index. Do not rely on multi-display targeting.</li><li><strong>Scroll location:</strong> the adapter validates a point but cannot express scroll-at-point through the pinned backend command. Direction and units also require backend-specific verification.</li><li><strong>Capture identity:</strong> the released screenshot response does not provide the width, height and scale fields expected by the current capture-identity path. Without an identity, subsequent coordinate-based input is refused. Synthetic capture fixtures do not prove this works with the released backend.</li></ul>
    <h2>Excluded surfaces</h2><p>The initial profile does not expose arbitrary shell commands, host file APIs, clipboard, PTY, Playwright execution, the backend's MCP server or its responses API. Filesystem access has its own confined service.</p>
    <p>The shipped <code>provision-catalog</code> workflow does not create computer-use services. Its MCP, ACP and filesystem provisioning support does not establish a CUA setup path or real-desktop acceptance.</p>
    <h2>Response semantics</h2><p>The pinned /cmd implementation can return HTTP 200 with a failure payload. Its response uses data-framed JSON with a text/plain media type, so callers must not infer success from the status code alone or assume ordinary JSON.</p>
    <h2>Input is a side effect</h2><p>A lost click response does not mean the click never happened. Never repeat input automatically after reconnect. Capability discovery must intersect backend support, local export policy and the caller's grant. Synthetic fixtures do not prove real parameter schemas, permission prompts, display scaling or focus behavior.</p>`, ['docs/integrations.md','docs/tasks.md','crates/tunnel-cua','crates/tunnel-cua-export']],
  ['filesystems', 'Filesystems', 'Confined files, shared across agent frameworks.', `
    <p class="lede">A shared TypeScript client speaks 9P2000.L over an authenticated consumer WebSocket to a scoped filesystem export.</p>
    <h2>Framework adapters</h2>${table(['Adapter','Source export','Purpose'],[['Files SDK','@agent-tunnel/client/files-sdk','Object-style operations over scoped files.'],['Mastra','@agent-tunnel/client/mastra','WorkspaceFilesystem integration.'],['just-bash','@agent-tunnel/client/just-bash','A filesystem for the in-process shell interpreter, not a remote host shell.'],['AI SDK','@agent-tunnel/client/ai-sdk','Files API integration through the shared client.']])}
    <p>These are export subpaths in the source package, not four independently published npm packages. The rebrand does not rename these identifiers. Use the checkout's package metadata rather than assuming a public registry release.</p>
    <h2>Provision and connect</h2><p>Use <code>examples/m6-catalog-fs.toml</code> through the <a href="/docs/setup">fresh-catalog workflow</a>. Declare the export's actual case behavior using <code>fs_case_sensitivity</code> and grant <code>fs:connect</code> plus the permitted file operations. Local export capabilities can narrow access further.</p><p>A GET to <code>/v1/devices/{device_id}/services/{service_id}/fs</code> returns the descriptor; a WebSocket upgrade with subprotocol <code>agent-tunnel.9p.v1</code> opens a 9P2000.L session. The token needs <code>fs:connect</code>. The binary bundle includes no filesystem consumer client; the TypeScript client is a separate source integration. The provisioning regression gate reads a generated file, not every adapter's full workflow.</p>
    <h2>Ownership and authorization</h2><p>The application owns the connection. Adapters borrow it and must not change its token, endpoint, root or grant. Closing one adapter must not close another adapter's handles. Cross-user connection sharing is prohibited.</p>
    <h2>Semantic boundaries</h2><ul><li>Paths are virtual and constrained to the exported root.</li><li>Write permission comes from server grants and local policy, not an SDK option.</li><li>Symlink and no-follow behavior must be enforced by the provider; a string-only path check is not enough.</li><li>Transport replay cannot establish whether a mutation completed.</li><li>SDK-native retries must not turn an unknown write outcome into a duplicate write.</li></ul>
    <h2>Integration caveats</h2><p>Files SDK needs its own matching FilesError class instance so failures keep their intended retry semantics. The pinned just-bash API includes synchronous metadata helpers that cannot perform asynchronous remote enumeration. Consult the source adapter contract before assuming complete filesystem equivalence.</p>
    <h2>Host support</h2><p>Filesystem exports require a Unix device host, such as Linux or macOS. On Windows, <code>tunnel-client config check</code> and <code>connect</code> refuse an fs export with <code>filesystem exports are unsupported on this host</code>. Enrolling a Windows device or building a Windows binary does not enable filesystem exports.</p><p>Linux now uses the bounded per-component resolver when symlinks are enabled, enforcing the provider's 32-hop and per-target bounds. With symlinks disabled it uses <code>openat2</code> where available, with a per-component fallback. This implementation change is not a blanket platform or adapter certification.</p>
    <h2>Verification scope</h2><p>Four native adapters have compilation/contract evidence. The shared TypeScript client and one adapter have real relay/device socket evidence. Upstream records include Linux resolver tests and corrections after their first hosted run; full Linux race/deletion evidence, second-host acceptance and all-adapter end-to-end coverage remain separate. No host or adapter tests were rerun for this website review.</p>`, ['docs/filesystem-api.md','docs/filesystem-adapters.md','packages/client/package.json','docs/tasks.md']],
  ['support', 'Support & Troubleshooting', 'Know the boundary before you depend on it.', `
    <p class="lede">Repository evidence is scoped. Development progress is not a production support commitment.</p>
    ${table(['Area','Available evidence','Still required'],[['Transport','Authenticated echo, ordered rotation and retained transport replay have local evidence.','Deployment-specific acceptance and platform coverage.'],['Cluster','Private relay routing and declared local cluster gates exist.','Open failure/recovery defects; no automatic Redis HA guarantee.'],['MCP','HTTP/stdio profiles and pinned fixture interoperability.','Remaining isolation, conformance and wider protocol coverage.'],['ACP','Official client bridge conversation and scoped cluster evidence.','Full milestone acceptance, key-rotation and saturation cases.'],['Filesystem','Shared client, four adapters and scoped real-socket tests.','Broader adapter and OS acceptance.'],['Computer use','Pinned command surface, adapter and synthetic fixtures.','Real OS/backend probes and disposable desktop VM acceptance.'],['Packaging','Use a published development archive when available, or build from the source checkout.','Private-alpha release gate and supported installation artifacts.']])}
    <h2>Client exit codes</h2><p>The implemented <code>tunnel-client</code> mapping distinguishes operator actions. Read the diagnostic alongside the process status.</p>
    ${table(['Exit','Meaning','Operator action'],[['0','Success or orderly stop','No action required.'],['1','Unexpected protocol, supervisor or signal failure','Investigate a defect or version mismatch.'],['2','Invalid invocation or configuration','Correct the command or profile.'],['3','Credential failure or stale authorization','Read the cause: credential refusal is terminal; stream authorization expiry may reconnect.'],['4','Transport failure or closed session','Check reachability and reconnect policy.'],['5','Deadline exceeded','Check latency and the configured bounded deadline.'],['7','OWNER_BUSY or RESOURCE_EXHAUSTED','Check ownership, capacity and reconnect limits; this does not resolve earlier operation outcomes.'],['130','Cancellation before orderly completion','Inspect interruption state; an orderly live-session stop returns 0 instead.']])}
    <p>With reconnect enabled, retryable failures normally produce lifecycle events rather than process exits. A finite attempt limit, disabled reconnect or terminal cause ends the process with the last cause's status. Do not infer operation completion from a reconnect or an exit code.</p>
    ${note('Exit 6 is reserved for unknown outcomes but has no producer in the current client. Do not rely on receiving it to detect every ambiguous effect. Client exit 130 also covers a second stop request and a drain timeout. The relay does not otherwise use this table: it returns 0 or 1, plus 130 for an interrupted serve or an abandoned writing command. Local doctor independently returns 0, 2 or 3.')}
    <h2>Configuration rejected</h2><p>Use client <code>config check</code> or relay <code>check-serve-config</code>, not the legacy bootstrap schema checker. Check unknown fields, endpoint scheme, namespace characters and rotation timing. A dry run does not verify referenced files.</p>
    <h2>Certificate or connection failure</h2><p>Run local <code>doctor</code>. Check the device key/certificate pairing, expiry and CA trust; verify the relay hostname and mTLS listener. Do not bypass validation or swap in test credentials.</p>
    <p>A device-identity refusal during control registration is now a non-retryable <code>CREDENTIAL_ERROR</code>, exit 3: check the profile device UUID, certificate SAN and catalog registration rather than repeatedly reconnecting. The response deliberately does not reveal which identity check failed. A catalog credential that is not yet valid remains a retryable transport error. The cluster's earlier unknown-key lookup can still close without this refusal reason and appear as <code>TRANSPORT_ERROR</code>; do not assume every identity failure is classified.</p>
    <h2>Operational surfaces</h2><p>No metrics endpoint, audit log, client <code>status</code> command or network doctor is supplied in this alpha. Relay logs go to stderr; retention and rotation are external responsibilities. Treat logs as sensitive: <code>connect --json</code> lifecycle events include local socket addresses and deadlines, even though they carry no payloads or credentials.</p><p><code>/livez</code> checks process liveness only. Cluster <code>/readyz</code> checks admission conditions, but a non-cluster relay always reports ready once serving, even when Redis authority is unavailable and requests return 503 <code>AUTHORIZATION_UNAVAILABLE</code>. Do not use that non-cluster response as a dependency-health guarantee. Neither endpoint proves an end-to-end capability works.</p>
    <h2>Redis connection diagnostics</h2><p>Current main reports bounded connection stages and failure classes in <code>serve</code>, <code>activate-first-incarnation</code>, <code>provision-catalog</code>, <code>recovery-observe</code> and <code>recover</code>. Older binaries may report only a generic connection failure.</p>
    ${code('Redis catalog connection failed; stage=connection_establishment lane=3/6 class=timeout')}
    <p>This example means the initial connection and two lanes opened, then lane three failed. The optional lane number identifies one of six authority connections opened after the initial connection. Recovery commands use the prefix <code>recovery Redis connection failed;</code>. These diagnostics use fixed words rather than URLs, hostnames, credentials or Redis reply text.</p>
    ${table(['Stage or class','What to check'],[['stage=tls_setup','Local TLS configuration and referenced certificate/key files.'],['stage=connection_establishment','DNS, TCP, TLS handshake or AUTH; inspect the class.'],['stage=ping / primary_identity','PING or INFO server access and replies.'],['stage=authority_profile / authority_identity','Authority configuration and deployment-incarnation prerequisites; do not bypass fences.'],['class=dns / refused / timeout / io','Name resolution, listener reachability, connection budget or transport failure.'],['class=tls_certificate / tls_alert / tls','Server trust, hostname and client certificate requirements.'],['class=auth / noperm','Redis credentials versus permission to run the required command.'],['class=reply / invalid_reply / run_id_conflict / config / catalog','Reply shape, Redis run identity, configuration or catalog refusal; retain the stage when reporting.']])}
    <p>Each startup or recovery connection gets a 10-second connection budget covering DNS, TCP, TLS and AUTH; subsequent commands have a 2-second deadline. This is not a 10-second bound for the whole startup. Live authority-lane reconnects remain capped at 2 seconds for the entire reconnect, including DNS, by the caller's deadline. Slow cold DNS can still defeat those reconnects; that limitation is open. Source and scoped regression tests were reviewed, not rerun as deployment acceptance.</p>
    <h2>Redis restart and backup</h2><p>Current main supports one narrow case: a single non-cluster relay's Redis restarting in place from its own durable AOF, retaining acknowledged writes. It does not cover replica promotion, restored backups or replaced volumes. Cluster Redis restarts and uncertain authority still require the recovery workflow with an external signing authority that is not shipped.</p>
    <p><strong>Automatic continuity:</strong> the optional top-level relay setting <code>redis_restart_continuity_seconds</code> accepts 1 to 60 seconds and is rejected with <code>[cluster]</code>. The relay must remain running across the Redis restart. It periodically records a token and can rebind the namespace to the new Redis run only when continuity and durability checks pass. Both startup and ongoing checks require <code>appendonly yes</code>, <code>appendfsync always</code> and <code>no-appendfsync-on-rewrite no</code>, with permission for <code>CONFIG GET</code>. The Fly template sets the interval to 5 seconds; this is not a global default.</p>
    <p><strong>Do not use continuity with failover or restore.</strong> A recent backup or replica may hold the token yet omit later acknowledged revocations. Never weaken the persistence settings at runtime: detection has an interval-plus-deadline window, and a crash inside it can still lose recent writes. A stopped or failing token loop cannot indefinitely authorize a later restart. These checks do not replace operator control of Redis's storage history.</p>
    <p><strong>Operator attestation:</strong> if the relay did not remain running, or continuity was not enabled, first verify that the same Redis restarted from its own data directory with no restore, volume replacement or replica promotion. Only then use the following command with the same single-relay configuration:</p>
    ${code('tunnel-relay rebind-redis-run --config /absolute/path/relay.toml --redis-restarted-in-place')}
    <p>The flag is an operator declaration, not an automated proof that data survived. The command preserves the namespace and incarnation and refuses an unbound namespace or cluster configuration. It does not clear a running relay's previously detected continuity mismatch. Do not use it to bypass a restore or lost-data refusal; follow externally approved recovery or provision a genuinely new deployment instead.</p>
    ${table(['Failure class','Meaning'],[['run_changed','The stored binding names an earlier Redis run; evaluate the supported in-place restart path.'],['unbound','The namespace has no incarnation or run binding, including an empty Redis.'],['continuity','The running relay did not find a permitted continuity token; it keeps refusing that run.'],['persistence','Required durability settings were absent or CONFIG GET was refused.']])}
    <p>Repository process evidence covers in-place restart/crash and selected lost-data refusals using shipped binaries; it is not hosted deployment acceptance or a new test run here. Devices may lose sessions and reconnect, and owner leases/backoff can delay resumed service. Non-cluster readiness remains insufficient to establish authority health.</p>
    <p>Redis backups still use operator tooling. Historical Redis 8.4.0 dogfood evidence found AOF transaction replay failures with the default user disabled and a separate relay ACL user. No least-privilege ACL profile is validated. Test your exact Redis version, persistence and ACL configuration without assuming a saved AOF restores authorization records or weakening authentication. Preserve membership and recovery state.</p>
    <h2>Reconnect limits</h2><p>After this process's own session ends, <code>OWNER_BUSY</code> is retried for up to 60 seconds; on a fresh process's first attempt it exits 7. A relay crash can retain ownership for the lease duration, up to 30 seconds. Current main's owner-local device control loop sends WebSocket Pings every 10 seconds and evicts after 30 seconds without any inbound frame, followed by a disconnect hand-off bounded at 5 seconds. These constants are not configurable. The client reconnects on its next attempt, not necessarily at exactly 30 seconds.</p><p>Repository evidence records an owner-local cut-path reconnect and a healthy idle session surviving the check. Older relays and devices attached through a non-owner cluster relay are not covered by this fix and can still retain stale ownership; an operator-managed relay restart interrupts its other sessions too. Reconnect does not restore in-flight operations or authorize replay.</p><p>A separate source-identified limitation remains: the client's control Pong can be held behind a pending OPEN or a full control queue, then fail its 5-second critical-response deadline and end a healthy session. This was not measured as a runtime occurrence. The liveness fix is not a claim of complete reconnect or saturation acceptance.</p>
    <h2>Rotation refusals</h2><p>Scoped dogfood evidence found transient 503 <code>PEER_UNAVAILABLE</code> refusals around data rotation, including on one relay, with <code>retry_after_ms</code> of 250. Respect retry guidance only for a known refused/not-dispatched operation; reconcile any ambiguous side effect before repeating it. Seamless rotation for every capability is not established by this observation.</p>
    <p>Current main resumes connector OPEN admission at rotation COMMIT, including the retiring phase, to match the owner. This addresses a separate intermittent <code>503 DEVICE_REJECTED</code> caused by the connector refusing new work as draining after the owner had resumed admission. Admission closes again if the active data carrier is lost, including during retirement. Source and focused regression tests cover these decisions; they were not rerun for this website review.</p>
    <p><strong>Remaining limit:</strong> the connector's writer stays frozen until ROTATE_COMPLETE even though new operations can be admitted earlier. If retirement stalls, output may wait for forced completion at the overlap deadline plus handshake grace, 30 + 10 seconds with defaults. This is a source-derived bound, not a measured latency guarantee. A shorter consumer timeout can leave an unknown operation outcome rather than an explicit refusal. Do not replay side effects merely because the response timed out. Complete rotation acceptance remains open.</p>
    <h2>Admission and cluster limits</h2><p>After a burst of stream releases, the owner may admit a consumer before the connector has retired those streams from its own capacity count. The consumer can receive a WebSocket 101 upgrade followed by a Close without a typed reason when the connector refuses the OPEN. This remains unresolved; an upgrade alone does not prove that work was admitted by the device.</p><p>Current main fixes a stale cached owner epoch after a device reconnects to the same relay: peer routing now binds to the freshly read owner generation rather than an older cached one. Scoped production-gate evidence supports the fix, but some peer-ingress refusals still end without response headers and can fail the shared HTTP/3 connection, interrupting other multiplexed streams. The routing fix removes a common trigger, not the remaining refusal defect. Complete cluster acceptance remains open; these runtime gates were not rerun for this website review.</p><p>Queue-saturation tests pin socket buffers only in the fixture. Production kernel buffers add OS-bounded capacity beyond the relay's configured application queues; the test's buffer sizes are not production limits. A graceful WebSocket Close also follows already-buffered records, so cancellation under saturation can take seconds while queued work continues. Do not assume immediate cancellation or blindly replay interrupted operations.</p>
    <h2>Echo retention limits</h2><p>Completed finite echoes now have explicit retention cleanup, addressing the earlier failure after 128 requests in one session. Other exits, including RESET, cancellation, authorization invalidation and an expired or disconnected consumer request, can still retain entries. They can exhaust capacity or break a rotation roster. A client reporting an active session is not proof that it can admit new work; automatic replacement of a retention-exhausted session remains planned. Do not increase limits or blindly repeat interrupted operations as a substitute for resolving their outcomes.</p>
    <h2>Connected but access denied</h2><p>Check the authenticated principal's tenant membership and device/service/operation grant, local export configuration and policy revision. Some inaccessible resources deliberately appear as not found rather than leaking their existence.</p>
    <h2>Catalog changes and revocation</h2><p>The <a href="/docs/setup">catalog-change CLI</a> adds records and replaces or revokes grants while the relay serves. It does not add a second tenant or renew an existing device certificate. A dry run checks local inputs, not current authority state. Refusals exit 1; a second stop signal can abandon a writing command with exit 130 and an unknown outcome.</p><p>Revocation is not retroactive cancellation of completed effects. A grant already admitted can remain authorized for up to five seconds. Device/credential revocation is also detected by session maintenance, which checks up to 64 sessions every 500 ms. That schedule and Redis latency are not an instantaneous global cutoff. Repository evidence measured one device's revocation and terminal credential refusal on reconnect; the live-session close for credential-only revocation was not measured. No revocation runtime tests were rerun for this website review.</p>
    <h2>Control-path stalls and authorization expiry</h2><p>The connector buffers stream input while authorization refresh is unconfirmed. If authorization expires, it discards that buffered input even when transport acknowledgements have already removed it from relay replay. Stall tolerance remains limited; transport acknowledgement is not application completion.</p><p><strong>Corrected measurements:</strong> the earlier claim that a two-second stall lost an echo used an experiment whose actual stall lasted at least five seconds. In the corrected Linux-container experiment, exact two- and three-second stalls each delivered 3 of 3 records; four- and 5.5-second stalls each delivered 2 of 3. These small samples are not a timeout guarantee, and they do not fully explain the earlier hosted failures.</p><p>Current main fixes unanswered echo waiters when the connector sends FIN or RESET: the relay produces <code>DEVICE_CLOSED</code> or <code>DEVICE_RESET</code>, with execution <code>unknown</code> for dispatched records and <code>not_dispatched</code> for queued records. Scoped container evidence now records consumer closure as a lapsed stall ends instead of waiting out the old 30-second timeout. This is an echo-path fix, not proof that every capability or network fault delivers a prompt error. Reconcile unknown side effects before retrying.</p><p>The connector also skips already-invalidated streams during expiry checks; a focused regression test covers one expiry across five ticks. Internal <code>StreamAuthCounters</code> expose unconfirmed streams, refreshes in flight, buffered input and expired streams in connection status and harness diagnostics, not a new CLI command. Harness hold fixes and these product fixes do not establish complete transport acceptance. Runtime tests were not rerun for this website review; hosted verification remains separate.</p>
    <h2>Interrupted operation</h2><p>Distinguish not-dispatched from unknown outcome. Reconcile the application state before retrying writes, clicks or prompts. Do not treat a transport acknowledgement or HTTP 202 as completion.</p>
    <h2>Reporting a problem</h2><p>Capture the source revision, platform, selected profile, redacted identifiers, phase and counters. Exclude tokens, private keys, tool payloads, screenshots of private data and user file contents.</p>`, ['docs/tasks.md','docs/runtime.md','docs/testing.md']],
];
const provenance = JSON.parse(fs.readFileSync(path.join(__dirname, 'provenance.json'), 'utf8'));
// Candidate pages can be verified before advancing the successful review baseline.
if (process.env.DOCS_REVIEW_REVISION) provenance.reviewedOriginMain = process.env.DOCS_REVIEW_REVISION;
if (process.env.DOCS_REVIEW_DATE) provenance.reviewedDate = process.env.DOCS_REVIEW_DATE;
for (const [slug, label, title, body, sources] of pages) {
  const nav = pages.map(([id, name]) => `<a href="/docs/${id === 'index' ? '' : id}"${id === slug ? ' aria-current="page"' : ''}>${name}</a>`).join('');
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${escape(title)} Agent Uplink development documentation."><title>${label} | Agent Uplink Docs</title><link rel="stylesheet" href="/docs.css"><link rel="stylesheet" href="/theme.css"><script src="/theme.js"></script><script src="/releases.js" defer></script></head><body><a class="skip" href="#content">Skip to content</a><header class="docs-header"><a class="docs-brand" href="/">Agent Uplink</a><nav aria-label="Site"><a href="/docs/">Documentation</a><a href="/brand-lab">Brand lab</a></nav></header><div class="docs-layout"><aside class="docs-nav"><p>DOCUMENTATION</p><nav aria-label="Documentation">${nav}</nav></aside><main id="content"><p class="kicker">DEVELOPMENT DOCUMENTATION / ${label.toUpperCase()}</p><h1>${title}</h1>${body}<section class="provenance"><h2>Source & review</h2><p>Reviewed against <code>${provenance.reviewedOriginMain.slice(0, 12)}</code> on ${provenance.reviewedDate}. Based on ${sources.map(s => `<code>${s}</code>`).join(', ')}. Historical test evidence is not a new test run.</p></section><footer><a href="/docs/setup">Setup</a><a href="/docs/support">Support boundaries</a><a href="/">Agent Uplink home</a></footer></main></div></body></html>`;
  fs.mkdirSync(path.join(__dirname, 'docs'), { recursive: true });
  fs.writeFileSync(path.join(__dirname, 'docs', `${slug}.html`), html);
}
console.log(`Built ${pages.length} documentation pages.`);
